export const getRandomQuestion = () => {
  const randomIndex = Math.floor(Math.random() * knowledgeQuestions.length);
  return knowledgeQuestions[randomIndex];
};

// Helper function to get questions by expertise
export const getQuestionsByExpertise = (expertise) => {
  return knowledgeQuestions.filter(q => q.expertise === expertise);
};

// Helper function to get questions by difficulty
export const getQuestionsByDifficulty = (difficulty) => {
  return knowledgeQuestions.filter(q => q.difficulty === difficulty);
};

// Helper function to get questions by expertise and difficulty
export const getQuestionsByExpertiseAndDifficulty = (expertise, difficulty) => {
  return knowledgeQuestions.filter(
    q => q.expertise === expertise && q.difficulty === difficulty
  );
};

// Helper function to get a random question based on criteria
export const getRandomQuestionByCriteria = (expertise, difficulty) => {
  let filteredQuestions = knowledgeQuestions;

  if (expertise) {
    filteredQuestions = filteredQuestions.filter(q => q.expertise === expertise);
  }

  if (difficulty) {
    filteredQuestions = filteredQuestions.filter(q => q.difficulty === difficulty);
  }

  if (filteredQuestions.length === 0) {
    return null;
  }

  const randomIndex = Math.floor(Math.random() * filteredQuestions.length);
  return filteredQuestions[randomIndex];
};
